<?php
declare(strict_types=1);
require __DIR__.'/bootstrap_saas.php';
saas_require_login();
$tourId=saas_require_tour();
saas_require_permission('finance.manage');
$db=saas_db();$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 saas_check_csrf();
 try{
  $action=(string)($_POST['action']??'');
  if($action==='add_expense'||$action==='add_income'){
   $category=trim((string)($_POST['category']??''));$description=trim((string)($_POST['description']??''));$amount=(float)($_POST['amount']??0);$date=trim((string)($_POST['date']??date('Y-m-d')));$from=trim((string)($_POST['received_from']??''));
   if($category==='')throw new RuntimeException('Category is required.');if($amount<=0)throw new RuntimeException('Amount must be greater than zero.');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Invalid date.');
   if($action==='add_expense'){$q=$db->prepare('INSERT INTO expenses(tour_id,category,description,amount,expense_date,created_by) VALUES(?,?,?,?,?,?)');$q->execute([$tourId,$category,$description?:null,round($amount,2),$date,saas_user_id()]);$id=(int)$db->lastInsertId();$type='expense';}
   else{$q=$db->prepare('INSERT INTO incomes(tour_id,category,description,amount,received_from,income_date,created_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$tourId,$category,$description?:null,round($amount,2),$from?:null,$date,saas_user_id()]);$id=(int)$db->lastInsertId();$type='income';}
   saas_audit($type.'.created',$type,$id,json_encode(['category'=>$category,'amount'=>$amount],JSON_UNESCAPED_UNICODE));$ok=ucfirst($type).' recorded.';
  }elseif($action==='delete_expense'||$action==='delete_income'){
   $id=(int)($_POST['id']??0);$table=$action==='delete_expense'?'expenses':'incomes';$type=$action==='delete_expense'?'expense':'income';$q=$db->prepare("SELECT id,amount FROM {$table} WHERE id=? AND tour_id=? FOR UPDATE");$q->execute([$id,$tourId]);$row=$q->fetch();if(!$row)throw new RuntimeException(ucfirst($type).' not found.');$q=$db->prepare("DELETE FROM {$table} WHERE id=? AND tour_id=?");$q->execute([$id,$tourId]);saas_audit($type.'.deleted',$type,$id,json_encode(['amount'=>$row['amount']]));$ok=ucfirst($type).' deleted.';
  }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM incomes WHERE tour_id=?');$q->execute([$tourId]);$incomeTotal=(float)$q->fetchColumn();
$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_id=?');$q->execute([$tourId]);$paymentTotal=(float)$q->fetchColumn();
$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE tour_id=?');$q->execute([$tourId]);$expenseTotal=(float)$q->fetchColumn();
$q=$db->prepare('SELECT COALESCE(SUM(fee-discount),0) FROM tour_passengers WHERE tour_id=? AND status<>'CANCELLED'');$q->execute([$tourId]);$receivable=(float)$q->fetchColumn();
$q=$db->prepare('SELECT e.*,u.name creator FROM expenses e LEFT JOIN users u ON u.id=e.created_by WHERE e.tour_id=? ORDER BY e.expense_date DESC,e.id DESC');$q->execute([$tourId]);$expenses=$q->fetchAll();
$q=$db->prepare('SELECT i.*,u.name creator FROM incomes i LEFT JOIN users u ON u.id=i.created_by WHERE i.tour_id=? ORDER BY i.income_date DESC,i.id DESC');$q->execute([$tourId]);$incomes=$q->fetchAll();
$collected=$paymentTotal+$incomeTotal;$balance=$collected-$expenseTotal;$due=max(0,$receivable-$paymentTotal);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tour Finance</title><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#f4f7fb;margin:0;color:#172033}.wrap{max-width:1250px;margin:25px auto;padding:0 16px}.box{background:#fff;border-radius:16px;padding:20px;margin-bottom:18px;box-shadow:0 6px 22px #0000000b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{border:1px solid #eaecf0;border-radius:12px;padding:14px}.stat b{display:block;font-size:21px;margin-top:5px}.muted{color:#667085;font-size:13px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}label{display:block;font-size:13px;font-weight:700;margin:10px 0 5px}input,textarea,button{width:100%;padding:10px;border:1px solid #d0d5dd;border-radius:9px;font:inherit}textarea{min-height:65px;resize:vertical}button{margin-top:12px;background:#155eef;color:#fff;border-color:#155eef;cursor:pointer;font-weight:700}.danger{background:#fff;color:#b42318;border-color:#fecdca;padding:6px 9px;margin:0;font-size:12px}.msg{padding:11px;border-radius:9px;margin-bottom:15px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #eee;text-align:left}.tablewrap{overflow:auto}.profit{font-weight:800}@media(max-width:900px){.stats{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}}@media(max-width:550px){.stats,.fields{grid-template-columns:1fr}}
</style></head><body><main class="wrap"><p><a href="saas_dashboard.php">← Dashboard</a></p><h1>Tour Finance</h1><?php if($ok):?><div class="msg ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=saas_h($error)?></div><?php endif;?><section class="box stats"><div class="stat"><span class="muted">Passenger receivable</span><b><?=number_format($receivable,2)?></b></div><div class="stat"><span class="muted">Passenger payments</span><b><?=number_format($paymentTotal,2)?></b></div><div class="stat"><span class="muted">Other income</span><b><?=number_format($incomeTotal,2)?></b></div><div class="stat"><span class="muted">Total expenses</span><b><?=number_format($expenseTotal,2)?></b></div></section><section class="box"><strong>Cash position:</strong> <?=number_format($balance,2)?> &nbsp; <span class="muted">(passenger payments + other income − expenses)</span> &nbsp; <strong>Passenger due:</strong> <?=number_format($due,2)?></section><div class="grid"><section class="box"><h2>Add expense</h2><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="add_expense"><label>Category</label><input name="category" placeholder="Transport, Hotel, Food..." required><div class="fields"><div><label>Amount</label><input type="number" name="amount" min="0.01" step="0.01" required></div><div><label>Date</label><input type="date" name="date" value="<?=date('Y-m-d')?>" required></div></div><label>Description</label><textarea name="description"></textarea><button>Save expense</button></form></section><section class="box"><h2>Add other income</h2><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="add_income"><label>Category</label><input name="category" placeholder="Sponsor, Donation, Other..." required><div class="fields"><div><label>Amount</label><input type="number" name="amount" min="0.01" step="0.01" required></div><div><label>Date</label><input type="date" name="date" value="<?=date('Y-m-d')?>" required></div></div><label>Received from</label><input name="received_from"><label>Description</label><textarea name="description"></textarea><button>Save income</button></form></section></div><div class="grid"><section class="box"><h2>Expenses</h2><div class="tablewrap"><table><tr><th>Date</th><th>Category</th><th>Amount</th><th></th></tr><?php foreach($expenses as $e):?><tr><td><?=saas_h($e['expense_date'])?></td><td><?=saas_h($e['category'])?><div class="muted"><?=saas_h($e['description']??'')?></div></td><td><?=number_format((float)$e['amount'],2)?></td><td><form method="post" onsubmit="return confirm('Delete this expense?')"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="delete_expense"><input type="hidden" name="id" value="<?=$e['id']?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></table><?php if(!$expenses):?><p class="muted">No expenses recorded.</p><?php endif;?></div></section><section class="box"><h2>Other income</h2><div class="tablewrap"><table><tr><th>Date</th><th>Category</th><th>Amount</th><th></th></tr><?php foreach($incomes as $i):?><tr><td><?=saas_h($i['income_date'])?></td><td><?=saas_h($i['category'])?><div class="muted"><?=saas_h($i['received_from']??'')?></div></td><td><?=number_format((float)$i['amount'],2)?></td><td><form method="post" onsubmit="return confirm('Delete this income?')"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="delete_income"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></table><?php if(!$incomes):?><p class="muted">No other income recorded.</p><?php endif;?></div></section></div></main></body></html>
